beforeExample:
public class Test {
    public void foo() {
        java.lang.StringBuffer sb = new java.lang.StringBuffer("hello");
        sb.append("world");
        System.out.println(sb.toString());
    }
}

afterExample:
public class Test {
    public void foo() {
        java.lang.StringBuilder sb = new java.lang.StringBuilder("hello");
        sb.append("world");
        System.out.println(sb.toString());
    }
}

negativeExample:
public class Test {
    // Not a local variable initializer (field)
    private java.lang.StringBuffer fieldBuffer = new java.lang.StringBuffer("field");

    // Not a local variable initializer (method return)
    public java.lang.StringBuffer createBuffer() {
        return new java.lang.StringBuffer("shared");
    }

    // Not a local variable initializer (method argument)
    public void processBuffer(java.lang.StringBuffer buffer) {
        buffer.append("processed");
    }
    public void callProcessBuffer() {
        processBuffer(new java.lang.StringBuffer("param"));
    }
}
